def price_for(model: str) -> dict[str, float]:
    if not model:
        return DEFAULT_PRICE
    if model in PRICING:
        return PRICING[model]
    base = model.split("[")[0]
    for k in PRICING:
        if base.startswith(k) or k in base:
            return PRICING[k]
    unknown_models.add(model)
    return DEFAULT_PRICE

def parse_ts(s: str) -> datetime:
    if s.endswith("Z"):
        s = s[:-1] + "+00:00"
    return datetime.fromisoformat(s)

def turns_of(path: Path, seen_ids: set[str]) -> list[tuple[datetime, int, int, int, str]]:
    """Parse one JSONL. Skip turns whose message.id was already counted globally."""
    out = []
    with path.open(errors="replace") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                obj = json.loads(line)
            except Exception:
                continue
            msg = obj.get("message")
            if not isinstance(msg, dict):
                continue
            usage = msg.get("usage")
            if not isinstance(usage, dict):
                continue
            try:
                ts = parse_ts(obj["timestamp"])
            except Exception:
                continue
            mid = msg.get("id")
            if mid:
                if mid in seen_ids:
                    continue
                seen_ids.add(mid)
            cc = usage.get("cache_creation_input_tokens", 0) or 0
            cr = usage.get("cache_read_input_tokens", 0) or 0
            inp = usage.get("input_tokens", 0) or 0
            model = msg.get("model") or usage.get("model") or ""
            out.append((ts, cc, cr, inp, model))
    out.sort(key=lambda x: x[0])
    return out

