def bucket(g: float) -> str:
    if g < 5:
        return "<5min"
    if g < 15:
        return "5-15min"
    if g < 30:
        return "15-30min"
    if g < 60:
        return "30-60min"
    if g < 240:
        return "1-4hr"
    return ">4hr"

